// Package fileset implements sdkgen's file-ownership contract: generated
// files carry a standard header, the generator deterministically owns its
// complete output set so stale files are removed on regeneration, and
// handwritten files are never touched.
package fileset

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
)

// Marker identifies sdkgen-owned files. It follows the Go convention for
// generated-code headers and must appear near the top of every generated file.
const Marker = "Code generated by sdkgen. DO NOT EDIT."

// markerScanLimit bounds how far into a file the marker is searched for.
const markerScanLimit = 512

// CommentStyle selects the comment leader for the generated-by header.
type CommentStyle int

const (
	Slash CommentStyle = iota // //
	Hash                      // #
)

// Header returns the generated-by header for a style, including the blank
// line separating it from content. No timestamps or versions: headers must be
// byte-stable across runs.
func Header(style CommentStyle) []byte {
	switch style {
	case Hash:
		return []byte("# " + Marker + "\n\n")
	default:
		return []byte("// " + Marker + "\n\n")
	}
}

// File is one generated file. Path is slash-separated and relative to the
// emitter's output root; Content excludes the header, which is injected on
// write.
type File struct {
	Path    string
	Content []byte
}

// FileSet is a deterministic set of generated files.
type FileSet struct {
	files map[string]File
}

func New() *FileSet {
	return &FileSet{files: map[string]File{}}
}

func (s *FileSet) Add(path string, content []byte) error {
	if _, ok := s.files[path]; ok {
		return fmt.Errorf("duplicate generated file %s", path)
	}
	s.files[path] = File{Path: path, Content: content}
	return nil
}

func (s *FileSet) Len() int {
	return len(s.files)
}

// Files returns the set sorted by path.
func (s *FileSet) Files() []File {
	out := make([]File, 0, len(s.files))
	for _, f := range s.files {
		out = append(out, f)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
	return out
}

// Rendered returns the on-disk bytes for f: header, then content.
func Rendered(f File, style CommentStyle) []byte {
	header := Header(style)
	out := make([]byte, 0, len(header)+len(f.Content))
	out = append(out, header...)
	out = append(out, f.Content...)
	return out
}

// IsGenerated reports whether on-disk content carries the sdkgen marker.
func IsGenerated(content []byte) bool {
	if len(content) > markerScanLimit {
		content = content[:markerScanLimit]
	}
	return bytes.Contains(content, []byte(Marker))
}

// Report summarizes a Reconcile.
type Report struct {
	Written []string
	Deleted []string
}

// Reconcile makes root match set: changed and missing files are written with
// the generated-by header, and files under root that carry the marker but are
// no longer in the set are deleted. Files without the marker are never
// touched, so handwritten siblings are structurally safe.
func Reconcile(root string, set *FileSet, style CommentStyle) (Report, error) {
	var report Report
	expected := map[string]bool{}
	for _, f := range set.Files() {
		expected[f.Path] = true
		want := Rendered(f, style)
		abs := filepath.Join(root, filepath.FromSlash(f.Path))
		got, err := os.ReadFile(abs)
		if err == nil && bytes.Equal(got, want) {
			continue
		}
		if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
			return report, err
		}
		if err := os.WriteFile(abs, want, 0o644); err != nil {
			return report, err
		}
		report.Written = append(report.Written, f.Path)
	}

	stale, err := generatedFiles(root, func(rel string) bool { return !expected[rel] })
	if err != nil {
		return report, err
	}
	for _, rel := range stale {
		if err := os.Remove(filepath.Join(root, filepath.FromSlash(rel))); err != nil {
			return report, err
		}
		report.Deleted = append(report.Deleted, rel)
	}
	pruneEmptyDirs(root, stale)
	return report, nil
}

// DriftKind classifies one entry in a check report.
type DriftKind int

const (
	Modified DriftKind = iota // exists with different bytes
	Missing                   // expected but absent from the tree
	Stale                     // generated file present but no longer expected
)

func (k DriftKind) String() string {
	switch k {
	case Modified:
		return "modified"
	case Missing:
		return "missing"
	default:
		return "stale"
	}
}

type DriftEntry struct {
	Kind DriftKind
	Path string // repo-relative when produced by the pipeline
}

type Drift []DriftEntry

// Check compares the rendered set against root without mutating anything.
func Check(root string, set *FileSet, style CommentStyle) (Drift, error) {
	var drift Drift
	expected := map[string]bool{}
	for _, f := range set.Files() {
		expected[f.Path] = true
		want := Rendered(f, style)
		got, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(f.Path)))
		switch {
		case os.IsNotExist(err):
			drift = append(drift, DriftEntry{Kind: Missing, Path: f.Path})
		case err != nil:
			return nil, err
		case !bytes.Equal(got, want):
			drift = append(drift, DriftEntry{Kind: Modified, Path: f.Path})
		}
	}
	stale, err := generatedFiles(root, func(rel string) bool { return !expected[rel] })
	if err != nil {
		return nil, err
	}
	for _, rel := range stale {
		drift = append(drift, DriftEntry{Kind: Stale, Path: rel})
	}
	sort.Slice(drift, func(i, j int) bool { return drift[i].Path < drift[j].Path })
	return drift, nil
}

// generatedFiles walks root and returns slash-relative paths of marker-bearing
// files matching the filter. A missing root is an empty result.
func generatedFiles(root string, filter func(rel string) bool) ([]string, error) {
	var out []string
	err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			if os.IsNotExist(err) && path == root {
				return filepath.SkipAll
			}
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if !filter(rel) {
			return nil
		}
		generated, err := hasMarker(path)
		if err != nil {
			return err
		}
		if generated {
			out = append(out, rel)
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	sort.Strings(out)
	return out, nil
}

func hasMarker(path string) (bool, error) {
	f, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer func() { _ = f.Close() }()
	head := make([]byte, markerScanLimit)
	n, err := io.ReadFull(f, head)
	if err != nil && err != io.EOF && err != io.ErrUnexpectedEOF {
		return false, err
	}
	return bytes.Contains(head[:n], []byte(Marker)), nil
}

// pruneEmptyDirs removes directories left empty by deletions, walking up from
// each deleted file toward root.
func pruneEmptyDirs(root string, deleted []string) {
	for _, rel := range deleted {
		dir := filepath.Dir(filepath.Join(root, filepath.FromSlash(rel)))
		for dir != root && len(dir) > len(root) {
			if err := os.Remove(dir); err != nil {
				break // not empty or already gone
			}
			dir = filepath.Dir(dir)
		}
	}
}

// SyncDirs makes got match want byte-for-byte: files that differ or are
// missing are written, and files under got that are absent from want are
// deleted unless ignore filters them out. It is the mutating counterpart of
// CompareDirs, sharing its staleness definition so a sync always satisfies a
// subsequent compare.
func SyncDirs(want, got string, ignore func(rel string) bool) error {
	drift, err := CompareDirs(want, got, true, ignore)
	if err != nil {
		return err
	}
	var deleted []string
	for _, entry := range drift {
		abs := filepath.Join(got, filepath.FromSlash(entry.Path))
		switch entry.Kind {
		case Modified, Missing:
			content, err := os.ReadFile(filepath.Join(want, filepath.FromSlash(entry.Path)))
			if err != nil {
				return err
			}
			if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
				return err
			}
			if err := os.WriteFile(abs, content, 0o644); err != nil {
				return err
			}
		case Stale:
			if err := os.Remove(abs); err != nil {
				return err
			}
			deleted = append(deleted, entry.Path)
		}
	}
	pruneEmptyDirs(got, deleted)
	return nil
}

// CompareDirs byte-compares the tree under want (a scratch render) against
// got (the checked-in tree). Paths in the result are relative to got. When
// detectStale is true, files under got that are absent from want are reported
// as stale; ignore filters relative paths out of stale detection entirely.
func CompareDirs(want, got string, detectStale bool, ignore func(rel string) bool) (Drift, error) {
	var drift Drift
	expected := map[string]bool{}
	err := filepath.WalkDir(want, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			if os.IsNotExist(err) && path == want {
				return filepath.SkipAll
			}
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(want, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		expected[rel] = true
		wantBytes, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		gotBytes, err := os.ReadFile(filepath.Join(got, filepath.FromSlash(rel)))
		switch {
		case os.IsNotExist(err):
			drift = append(drift, DriftEntry{Kind: Missing, Path: rel})
		case err != nil:
			return err
		case !bytes.Equal(wantBytes, gotBytes):
			drift = append(drift, DriftEntry{Kind: Modified, Path: rel})
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	if detectStale {
		err := filepath.WalkDir(got, func(path string, d os.DirEntry, err error) error {
			if err != nil {
				if os.IsNotExist(err) && path == got {
					return filepath.SkipAll
				}
				return err
			}
			if d.IsDir() {
				return nil
			}
			rel, err := filepath.Rel(got, path)
			if err != nil {
				return err
			}
			rel = filepath.ToSlash(rel)
			if expected[rel] || (ignore != nil && ignore(rel)) {
				return nil
			}
			drift = append(drift, DriftEntry{Kind: Stale, Path: rel})
			return nil
		})
		if err != nil {
			return nil, err
		}
	}
	sort.Slice(drift, func(i, j int) bool { return drift[i].Path < drift[j].Path })
	return drift, nil
}
